#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker (a UArenaScoreTracker* UObject created with NewObject in BeginPlay) lacked a UPROPERTY() macro in Source/PixelArena/ArenaGameMode.h, so Unreal's garbage collector did not see the reference and purged the object during the ~60-second GC pass (logged at 21:05:13), leaving ScoreTracker dangling and causing an access violation in UArenaScoreTracker::AddPoints when OnGoalScored ran.",
  "no_colors_cause": "Config/DefaultGame.ini sets bCookAll=False and only cooks /Game/Maps/Arena and /Game/Data/Effects, omitting /Game/Data/Palettes. Because /Game/Data/Palettes/DA_Primary is loaded dynamically via LoadObject by string path in AArenaGameMode::BeginPlay rather than statically referenced by a cooked map, the cooker excluded it from the packaged pak file, causing LoadObject to return null and the HUD to fall back to gray."
}
